    auto bad_left = [&](int k) -> int {
        if (k < 2) {
            return 0;
        }
        return pref_bad[k - 2];
    };
    auto bad_right = [&](int k) -> int {
        if (k >= n - 1) {
            return 0;
        }
        return tot_bad - pref_bad[k];
    };
    auto bad_bridge = [&](int k) -> int {
        if (k <= 0 || k >= n - 1) {
            return 0;
        }
        return (s[k + 1] - s[k - 1] < G) ? 1 : 0;
    };

    for (int k = 0; k < n; ++k) {
        int bl = bad_left(k);
        int br = bad_right(k);
        int bb = bad_bridge(k);
        int tb = bl + br + bb;
        if (tb > 1) {
            continue; // 坏间隔多于一处
        }
        int64 first_t = (k != 0 ? s[0] : s[1]);
        int64 last_t = (k != n - 1 ? s[n - 1] : s[n - 2]);
        if (tb == 0) {
            // t 内部已无坏间隔：尝试最左 / 最右 / 宽缝
            if (first_t >= G + 1) {
                return true;
            }
            if (last_t <= m - G) {
                return true;
            }
            int64 mx = -1;
            if (k >= 2) {
                mx = max(mx, pref_max[k - 2]);
            }
            if (k + 1 <= n - 2) {
                mx = max(mx, suf_max[k + 1]);
            }
            if (k > 0 && k < n - 1) {
                mx = max(mx, s[k + 1] - s[k - 1]);
            }
            if (mx >= 2 * G) {
                return true;
            }
            continue;
        }
        int64 u = 0, v = 0;
        bool ok = false;
        if (bb == 1 && bl == 0 && br == 0) {
            u = s[k - 1];
            v = s[k + 1];
            ok = true;
        } else if (bl == 1 && br == 0 && bb == 0) {
            int idx = pref_large[k - 2];
            u = s[idx];
            v = s[idx + 1];
            ok = true;
        } else if (br == 1 && bl == 0 && bb == 0) {
            int idx = suf_small[k + 1];
            if (idx == INT_MAX) {
                continue;
            }
            u = s[idx];
            v = s[idx + 1];
            ok = true;
        }
        if (!ok) {
            continue;
        }
        if (v - u < 2 * G) {
            continue;
        }
        int64 L = max<int64>(1, u + G);
        int64 R = min(m, v - G);
        if (L <= R) {
            return true;
        }
    }
    return false;
}

static int64 solve_one(int n, int64 m, vector<int64> a) {
    sort(a.begin(), a.end());
    int64 lo = 0, hi = m; // 二分最大可行 G
    while (lo < hi) {
        int64 mid = (lo + hi + 1) / 2;
        if (feasible(n, m, a, mid)) {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }
    return lo;
}

